const evento = $json;

const resumoOsv = String(evento.contexto_osv?.resumo ||
  'OSV: resultado ainda não disponível para esta análise. Isso não indica ausência de vulnerabilidades.').slice(0, 1000);

const contexto = {
  installation_id: evento.meta?.tenant_id,
  repositorio: evento.repositorio?.full_name,
  numero_pr: evento.pr?.numero,
  id_evento: evento.meta?.id_evento,
  task_run_id: evento.meta?.execution_id,
  osv_resumo: resumoOsv,
};

const autor = evento.pr?.autor?.login;
const motivo = evento.risco?.motivo || evento.risco?.explicacao;

if (
  evento.evento?.tipo !== 'aguardando_aprovacao' ||
  !Number.isSafeInteger(contexto.installation_id) ||
  contexto.installation_id <= 0 ||
  !contexto.repositorio ||
  !Number.isSafeInteger(contexto.numero_pr) ||
  contexto.numero_pr <= 0 ||
  !contexto.id_evento ||
  !contexto.task_run_id ||
  !autor ||
  !motivo
) {
  throw new Error('Evento de aprovação incompleto ou incompatível.');
}

const valorBotao = JSON.stringify(contexto);

if (valorBotao.length > 2000) {
  throw new Error('Contexto dos botões excede o limite do Slack.');
}
const slack_payload = {
  text: `Aprovação pendente: ${contexto.repositorio} #${contexto.numero_pr}\n${resumoOsv}`,
  blocks: [
    {
      type: 'section',
      text: {
        type: 'plain_text',
        text:
          `PR aguardando aprovação\n` +
          `${contexto.repositorio} #${contexto.numero_pr}\n` +
          `Autor: ${autor}`,
      },
    },
    {
       type: 'section',
      text: {
        type: 'plain_text',
        text: `Motivo do risco:\n${String(motivo).slice(0, 2800)}`,
      },
    },
    {
      type: 'section',
      text: { type: 'plain_text', text: 'Contexto OSV para a decisão:\n' + resumoOsv },
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Aprovar' },
          style: 'primary',
          action_id: 'aprovar',
          value: valorBotao,
        },
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Pedir revisão' },
          action_id: 'solicitar_alteracao',
          value: valorBotao,
        },
      ],
    },
  ],
};
return {
  json: {
    ...evento,
    slack_payload,
  },
};

const evento = $json;

const contexto = {
  installation_id: evento.meta?.tenant_id,
  repositorio: evento.repositorio?.full_name,
  numero_pr: evento.pr?.numero,
  id_evento: evento.meta?.id_evento,
  task_run_id: evento.meta?.execution_id,
};

const diagnostico = evento.execucao?.diagnostico;

if (
  evento.evento?.tipo !== 'falha_recuperavel' ||
  evento.execucao?.falha_recuperavel !== true ||
  !Number.isSafeInteger(contexto.installation_id) ||
  contexto.installation_id <= 0 ||
  !contexto.repositorio ||
  !Number.isSafeInteger(contexto.numero_pr) ||
  contexto.numero_pr <= 0 ||
  !contexto.id_evento ||
  !contexto.task_run_id ||
  typeof diagnostico !== 'string' ||
  !diagnostico.trim()
) {
  throw new Error('Evento de falha recuperável incompleto ou incompatível.');
}

const valorBotao = JSON.stringify(contexto);

if (valorBotao.length > 2000) {
  throw new Error('Contexto do botão excede o limite do Slack.');
}

const slack_payload = {
  text: `Falha recuperável: ${contexto.repositorio} #${contexto.numero_pr}`,
  blocks: [
    {
      type: 'section',
      text: {
        type: 'plain_text',
        text:
          `Falha recuperável na análise\n` +
          `${contexto.repositorio} #${contexto.numero_pr}`,
      },
    },
    {
      type: 'section',
      text: {
        type: 'plain_text',
        text: `Diagnóstico informado pelo núcleo:\n${diagnostico.slice(0, 2800)}`,
      },
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Reexecutar' },
          action_id: 'reexecutar_analise',
          value: valorBotao,
        },
      ],
    },
  ],
};

return {
  json: {
    ...evento,
    slack_payload,
  },
};

const crypto = require('crypto');

const entrada = $input.first();
const segredo = $env.SLACK_SIGNING_SECRET;

if (!segredo) {
  throw new Error('SLACK_SIGNING_SECRET indisponível no ambiente.');
}
const headers = Object.fromEntries(
  Object.entries(entrada.json.headers ?? {})
    .map(([nome, valor]) => [nome.toLowerCase(), valor])
);

const timestamp = headers['x-slack-request-timestamp'];
const assinatura = headers['x-slack-signature'];

if (
  typeof timestamp !== 'string' ||
  !/^\d+$/.test(timestamp) ||
  typeof assinatura !== 'string' ||
  !/^v0=[0-9a-f]{64}$/.test(assinatura)
) {
  throw new Error('Cabeçalhos de assinatura ausentes ou inválidos.');
}

const segundos = Number(timestamp);

if (
  !Number.isSafeInteger(segundos) ||
  Math.abs(Date.now() / 1000 - segundos) > 300
) {
  throw new Error('Requisição fora da janela de cinco minutos.');
}

if (!entrada.binary?.data) {
  throw new Error('Corpo bruto indisponível. Ative Raw Body no Webhook.');
}

const corpoBruto = await this.helpers.getBinaryDataBuffer(0, 'data');

const esperada =
  'v0=' +
  crypto
    .createHmac('sha256', segredo)
    .update(`v0:${timestamp}:`)
    .update(corpoBruto)
    .digest('hex');

const recebidaBuffer = Buffer.from(assinatura, 'utf8');
const esperadaBuffer = Buffer.from(esperada, 'utf8');

if (
  recebidaBuffer.length !== esperadaBuffer.length ||
  !crypto.timingSafeEqual(recebidaBuffer, esperadaBuffer)
) {
  throw new Error('Assinatura do Slack inválida.');
}

// O Webhook interpreta o formulário enviado pelo Slack.
// O corpo bruto acima foi usado exclusivamente para verificar a assinatura.
const payloadTexto = entrada.json.body?.payload;

if (typeof payloadTexto !== 'string') {
  throw new Error('Campo payload ausente ou inválido.');
}

const payload = JSON.parse(payloadTexto);

if (
  !payload ||
  typeof payload !== 'object' ||
  Array.isArray(payload) ||
  !['block_actions', 'view_submission'].includes(payload.type) ||
  typeof payload.user?.id !== 'string' ||
  !payload.user.id
) {
  throw new Error('Interação sem tipo suportado ou usuário válido.');
}

return [
  {
    json: {
      meta: {
        assinatura_verificada: true,
        recebido_em: new Date().toISOString(),
      },
      slack: payload,
    },
  },
];

