const crypto = require('crypto');

const segredo = $env.N8N_SEGREDO_ACOES;
const pedido = $json.pedido_acao;

if (!segredo) {
  throw new Error('N8N_SEGREDO_ACOES indisponível no ambiente.');
}

if (
  !pedido ||
  typeof pedido !== 'object' ||
  Array.isArray(pedido)
) {
  throw new Error('pedido_acao ausente ou inválido.');
}

// Este mesmo texto deverá ser enviado pelo HTTP Request.
const corpo = JSON.stringify(pedido);
const timestamp = Math.floor(Date.now() / 1000).toString();

const assinatura =
  'sha256=' +
  crypto
    .createHmac('sha256', segredo)
    .update(timestamp + '.', 'utf8')
    .update(corpo, 'utf8')
    .digest('hex');

return {
  json: {
    ...$json,
    requisicao_nucleo: {
      corpo,
      headers: {
        'X-Aprova-Timestamp': timestamp,
        'X-Aprova-Assinatura': assinatura,
      },
    },
  },
};

