const slack = $json.slack;

const tiposPorFormulario = {
  aprova_aprovacao: 'aprovar',
  aprova_revisao: 'solicitar_alteracao',
};

const callback = slack?.view?.callback_id;

const tipo = Object.prototype.hasOwnProperty.call(
  tiposPorFormulario,
  callback
)
  ? tiposPorFormulario[callback]
  : null;

if (
  $json.meta?.assinatura_verificada !== true ||
  slack?.type !== 'view_submission' ||
  !tipo
) {
  throw new Error('Envio de formulário inválido.');
}

const contexto = JSON.parse(slack.view.private_metadata);

if (
  contexto.tipo !== tipo ||
  contexto.usuario_slack !== slack.user?.id
) {
  throw new Error('Ação ou identidade incompatível com o formulário.');
}

const justificativa =
  slack.view.state?.values?.justificativa?.texto?.value?.trim();

if (
  typeof justificativa !== 'string' ||
  justificativa.length === 0 ||
  justificativa.length > 3000
) {
  throw new Error('Informe uma justificativa entre 1 e 3000 caracteres.');
}

if (
  !Number.isSafeInteger(contexto.installation_id) ||
  contexto.installation_id <= 0 ||
  !Number.isSafeInteger(contexto.numero_pr) ||
  contexto.numero_pr <= 0 ||
  typeof contexto.repositorio !== 'string' ||
  !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}\/[A-Za-z0-9._-]{1,100}$/.test(
    contexto.repositorio
  ) ||
  ['.', '..'].includes(contexto.repositorio.split('/')[1]) ||
  !slack.team?.id ||
  !slack.view.id
) {
  throw new Error('Contexto do PR incompleto ou inválido.');
}

const pedido = {
  id_acao: `slack:${slack.team.id}:${slack.view.id}`,
  tipo: tipo,
  usuario_slack: slack.user.id,
  repositorio: contexto.repositorio,
  numero_pr: contexto.numero_pr,
  installation_id: contexto.installation_id,
  ...(contexto.task_run_id ? { task_run_id: contexto.task_run_id } : {}),
  justificativa,
};

return {
  json: {
    ...$json,
    pedido_acao: pedido,
    retorno_acao: {
      origem: 'formulario',
      formulario: callback,
      canal_slack: contexto.canal_slack || null,
      usuario_slack: slack.user.id,
      justificativa,
    },
  },
};

const slack = $json.slack;
const acao = slack?.actions?.[0];

if (
  $json.meta?.assinatura_verificada !== true ||
  slack?.type !== 'block_actions' ||
  acao?.action_id !== 'reexecutar_analise' ||
  typeof acao.value !== 'string'
) {
  throw new Error('Interação de reexecução inválida.');
}

const contexto = JSON.parse(acao.value);

if (
  !contexto ||
  typeof contexto !== 'object' ||
  Array.isArray(contexto) ||
  !Number.isSafeInteger(contexto.installation_id) ||
  contexto.installation_id <= 0 ||
  !Number.isSafeInteger(contexto.numero_pr) ||
  contexto.numero_pr <= 0 ||
  typeof contexto.repositorio !== 'string' ||
  !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}\/[A-Za-z0-9._-]{1,100}$/.test(
    contexto.repositorio
  ) ||
  ['.', '..'].includes(contexto.repositorio.split('/')[1]) ||
  typeof slack.team?.id !== 'string' ||
  !slack.team.id ||
  typeof slack.user?.id !== 'string' ||
  !slack.user.id ||
  typeof acao.action_ts !== 'string' ||
  !/^\d+\.\d+$/.test(acao.action_ts)
) {
  throw new Error('Contexto da reexecução incompleto ou inválido.');
}

const pedido = {
  id_acao:
    `slack:reexecutar:${slack.team.id}:` +
    `${slack.user.id}:${acao.action_ts}`,
  tipo: 'reexecutar_analise',
  usuario_slack: slack.user.id,
  repositorio: contexto.repositorio,
  numero_pr: contexto.numero_pr,
  installation_id: contexto.installation_id,
  ...(contexto.task_run_id ? { task_run_id: contexto.task_run_id } : {}),
};

if (pedido.id_acao.length > 200) {
  throw new Error('Identificador da ação excede o limite da API.');
}

return {
  json: {
    ...$json,
    pedido_acao: pedido,
  },
};

// Com o nó 13 desativado, o pedido chega diretamente.
// Quando ele estiver ativo, recuperamos o contexto pelo nó 12.
const origem = $json.pedido_acao
  ? $json
  : $('12 | Assinar Pedido ao Núcleo').item.json;

const pedido = origem.pedido_acao;
const slack = origem.slack;
const contexto = slack?.view?.private_metadata
  ? JSON.parse(slack.view.private_metadata)
  : {};
const canal = origem.retorno_acao?.canal_slack ||
  slack?.channel?.id || slack?.container?.channel_id || contexto.canal_slack || null;
const formularioEnviado = slack?.type === 'view_submission';
const recebimento = formularioEnviado
  ? (pedido?.tipo === 'aprovar'
    ? 'Formulário de aprovação enviado.'
    : 'Formulário de revisão enviado.')
  : '';

if (!pedido?.usuario_slack) {
  throw new Error('Usuário do Slack não identificado para o retorno.');
}

const status = Number.isInteger($json.statusCode)
  ? $json.statusCode
  : null;

let corpo = $json.body;

if (typeof corpo === 'string') {
  try {
    corpo = JSON.parse(corpo);
  } catch {
    corpo = null;
  }
}

const nomes = {
  aprovar: 'Aprovação',
  solicitar_alteracao: 'Pedido de revisão',
  reexecutar_analise: 'Reexecução da análise',
};

const nome = nomes[pedido.tipo];

if (!nome) {
  throw new Error('Tipo de ação desconhecido.');
}

let mensagem;
let confirmada = false;

if (status === 202 && corpo?.status === 'aceito') {
  confirmada = true;
  const confirmacoes = {
    aprovar: 'O núcleo confirmou a aprovação da PR.',
    solicitar_alteracao: 'O núcleo confirmou o pedido de revisão da PR.',
    reexecutar_analise: 'O núcleo confirmou a reexecução da análise.',
  };
  mensagem = confirmacoes[pedido.tipo];
} else {
  const mensagens = {
    400: 'O núcleo recusou o pedido por dados inválidos.',
    401: 'O núcleo recusou a autenticação do pedido.',
    403: 'O núcleo não autorizou esta ação para seu usuário.',
    409: 'O núcleo informou que este pedido já foi processado.',
    500: 'O núcleo informou uma falha ao executar. Confira o resultado antes de tentar novamente.',
  };

  mensagem = mensagens[status] ??
    'Não recebemos uma confirmação válida do núcleo. A execução da ação não está confirmada.';
}

const simulacao = $json.simulacao === true || origem.simulacao === true;
const prefixo = simulacao ? '[SIMULAÇÃO — sem ação real]\n' : '';
const justificativa = pedido.justificativa?.trim() ||
  (pedido.tipo === 'reexecutar_analise'
    ? 'Não solicitada para a reexecução da análise.'
    : 'Não informada.');
const urlPr = `https://github.com/${pedido.repositorio}/pull/${pedido.numero_pr}`;
const autor = slack?.user?.real_name || slack?.user?.name || pedido.usuario_slack;
const rotuloAutor = formularioEnviado ? 'Autor do envio' : 'Autor do clique';
const resumo =
  `${prefixo}${recebimento ? recebimento + '\n' : ''}Ação: ${nome}\n` +
  `PR: ${pedido.repositorio} #${pedido.numero_pr}\n${urlPr}`;
const blocks = [
  { type: 'section', text: { type: 'plain_text', text: resumo } },
  { type: 'section', text: { type: 'mrkdwn', text: `*${rotuloAutor}:* <@${pedido.usuario_slack}>` } },
];
const textoJustificativa = (pedido.tipo === 'solicitar_alteracao'
  ? 'Justificativa / alterações solicitadas:\n'
  : 'Justificativa:\n') + justificativa;
for (let inicio = 0; inicio < textoJustificativa.length; inicio += 2900) {
  blocks.push({
    type: 'section',
    text: { type: 'plain_text', text: textoJustificativa.slice(inicio, inicio + 2900) },
  });
}
blocks.push({ type: 'section', text: { type: 'plain_text', text: mensagem } });

return {
  json: {
    resultado_nucleo: {
      status_http: status,
      confirmada: confirmada && !simulacao,
      simulacao,
    },
    slack_payload: {
      channel: canal,
      text: resumo + '\n' + rotuloAutor + ': ' + autor + ' (' + pedido.usuario_slack + ')\n' +
        textoJustificativa + '\n\n' + mensagem,
      blocks,
      mrkdwn: false,
      unfurl_links: false,
      unfurl_media: false,
    },
  },
};

const evento = $json;
const identidade = [evento.meta?.tenant_id, evento.meta?.execution_id, evento.repositorio?.full_name, evento.pr?.numero];
if (evento.evento?.tipo !== 'aguardando_aprovacao' ||
    !Number.isSafeInteger(identidade[0]) || identidade[0] <= 0 ||
    typeof identidade[1] !== 'string' || !identidade[1] ||
    typeof identidade[2] !== 'string' || !identidade[2] ||
    !Number.isSafeInteger(identidade[3]) || identidade[3] <= 0) {
  throw new Error('Contexto de aprovação inválido para consultar OSV.');
}
return { json: { ...evento, chave_osv: JSON.stringify(identidade) } };

function compativel(snapshot, evento) {
  if (!snapshot || snapshot.versao !== 1 ||
      !['concluida', 'incompleta', 'falha'].includes(snapshot.status) ||
      !Array.isArray(snapshot.dependencias) || snapshot.dependencias.length === 0 ||
      JSON.stringify(snapshot.identidade) !== evento.chave_osv ||
      (snapshot.sha && evento.pr?.sha && snapshot.sha !== evento.pr.sha) ||
      !Number.isFinite(Date.parse(snapshot.consultado_em))) return false;
  if (snapshot.dependencias.some(d => !d || !['nome', 'versao', 'ecossistema'].every(k => typeof d[k] === 'string' && d[k].trim()))) return false;
  const nomes = lista => JSON.stringify(lista.map(d => [d.ecossistema, d.nome, d.versao]).sort());
  return !Array.isArray(evento.dependencias) || evento.dependencias.length === 0 ||
    nomes(evento.dependencias) === nomes(snapshot.dependencias);
}
function apresentar(snapshot) {
  const prefixo = snapshot.status === 'concluida' ? 'Consulta OSV concluída' : snapshot.status === 'falha' ? 'Consulta OSV indisponível' : 'Consulta OSV com resultados parciais';
  const linhas = snapshot.dependencias.slice(0, 3).map(d =>
    d.nome + ' @ ' + d.versao + ' (' + d.ecossistema + '): ' + String(d.resumo || 'Resultado indisponível.').slice(0, 230));
  if (snapshot.total_dependencias > 3) linhas.push('Resumo limitado a 3 de ' + snapshot.total_dependencias + ' dependências; este resumo não é exaustivo.');
  return (prefixo + ' em ' + snapshot.consultado_em + '.\n\n' + linhas.join('\n\n')).slice(0, 1000);
}
const evento = $('02A | Identificar Contexto OSV').item.json;
let snapshot;
try { snapshot = JSON.parse($json.contexto); } catch {}
const valido = compativel(snapshot, evento);
const recente = valido && snapshot.status !== 'falha' && Date.now() - Date.parse(snapshot.consultado_em) <= 24 * 60 * 60 * 1000 &&
  Date.parse(snapshot.consultado_em) - Date.now() <= 300000;
